class Dsu:
    def __init__(self, n):
        self.pa = list(range(n))
        self.sz = [1] * n

    def find(self, x):
        if self.pa[x] != x:
            self.pa[x] = self.find(self.pa[x])
        return self.pa[x]

    def find_iter(self, x):
        # 迭代路径压缩（避免递归爆栈，链式毒瘤数据安全）
        while self.pa[x] != x:
            self.pa[x] = self.pa[self.pa[x]]  # 路径减半
            x = self.pa[x]
        return x

    def unite(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.sz[ra] < self.sz[rb]:
            ra, rb = rb, ra
        self.pa[rb] = ra
        self.sz[ra] += self.sz[rb]

    def same(self, a, b):
        return self.find(a) == self.find(b)


def main():
    dsu = Dsu(10)
    assert not dsu.same(0, 1)
    dsu.unite(0, 1)
    dsu.unite(1, 2)
    assert dsu.same(0, 2)
    assert not dsu.same(0, 3)
    dsu.unite(3, 4)
    dsu.unite(4, 2)
    assert dsu.same(3, 0)
    # 连通块数量
    roots = {dsu.find(i) for i in range(10)}
    assert len(roots) == 6  # 0..4 连成一块，5..9 各自
    # 与朴素对拍：随机合并验证 same 一致性
    import random
    random.seed(0)
    n = 200
    d = Dsu(n)
    comp = list(range(n))  # 朴素等价类

    def union_naive(a, b):
        ca, cb = comp[a], comp[b]
        for i in range(n):
            if comp[i] == cb:
                comp[i] = ca

    for _ in range(500):
        a, b = random.randrange(n), random.randrange(n)
        d.unite(a, b)
        union_naive(a, b)
        assert d.same(a, b) == (comp[a] == comp[b])
    print("dsu-basic OK")


if __name__ == "__main__":
    main()
